import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int maxConnections = sc.nextInt();
        int reserved = sc.nextInt();
        int n = sc.nextInt();
        int sum = 0;
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            int instances = sc.nextInt();
            int poolSize = sc.nextInt();
            int total = instances * poolSize;
            sum += total;
            System.out.println(name + " total=" + total);
        }
        int budget = maxConnections - reserved;
        System.out.println("sum=" + sum + " budget=" + budget);
        if (sum > budget) {
            System.out.println("verdict=OVERSUBSCRIBED over=" + (sum - budget));
        } else {
            System.out.println("verdict=OK headroom=" + (budget - sum));
        }
    }
}

