import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String> stages = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String sql = sc.nextLine().toUpperCase();
            String stage;
            if (sql.contains("DROP COLUMN")) {
                stage = "contract";
            } else if (sql.contains("SET NOT NULL")) {
                stage = "contract";
            } else if (sql.contains("ADD COLUMN")) {
                stage = !sql.contains("NOT NULL") || sql.contains("DEFAULT") ? "expand" : "unsafe";
            } else if (sql.contains("UPDATE")) {
                stage = "migrate";
            } else {
                stage = "unsafe";
            }
            stages.add(stage);
            System.out.println(stage);
        }
        int reached = 0;
        boolean ordered = true;
        for (String stage : stages) {
            int rank = switch (stage) {
                case "expand" -> 1;
                case "migrate" -> 2;
                case "contract" -> 3;
                default -> -1;
            };
            if (rank < 0 || rank < reached) {
                ordered = false;
            } else {
                reached = rank;
            }
        }
        System.out.println("order=" + (ordered ? "ok" : "ng"));
    }
}

