import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int base = sc.nextInt(), jitter = sc.nextInt(), n = sc.nextInt();
        Map<Integer, Integer> perTtl = new HashMap<>();
        for (int i = 0; i < n; i++) {
            // テナントとロケールを含めないと、別の利用者の結果を返してしまう
            String key = sc.next() + "/" + sc.next() + "/" + sc.next();
            int ttl = base + Math.floorMod(key.hashCode(), jitter + 1);
            perTtl.merge(ttl, 1, Integer::sum);
            System.out.println(key + " " + ttl);
        }
        int max = 0;
        for (int count : perTtl.values()) {
            max = Math.max(max, count);
        }
        System.out.println("maxSameExpiry=" + max);
        String verdict;
        if (n == 0) {
            verdict = "OK spread";
        } else if (jitter == 0) {
            verdict = "RISK all-same";
        } else if (max >= 2 && max * 2 > n) {
            verdict = "RISK concentrated";
        } else {
            verdict = "OK spread";
        }
        System.out.println(verdict);
    }
}

