import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String phase = sc.next();
        int n = sc.nextInt();
        Map<String, Set<String>> allowed = Map.of("expand", Set.of("add-nullable-column", "write-both"), "migrate", Set.of("write-both", "backfill", "switch-read"), "contract", Set.of("drop-old-column"));
        Map<String, String> meaning = Map.of("expand", "ADD_COMPATIBLE", "migrate", "BACKFILL_AND_SWITCH", "contract", "REMOVE_OLD");
        System.out.println("PHASE " + meaning.get(phase));
        int forbidden = 0;
        for (int k = 1; k <= n; k++) {
            String op = sc.next();
            boolean ok = !op.equals("add-not-null-column") && allowed.get(phase).contains(op);
            if (!ok) forbidden++;
            System.out.println(k + " " + op + " " + (ok ? "ALLOW" : "FORBID"));
        }
        System.out.println("FORBIDDEN " + forbidden);
    }
}

